  window.studentAskGuide=function(event){event.preventDefault();const input=document.getElementById("studentAiQuestion"),q=String(input?.value||"").trim().toLowerCase();let key="form";if(/study|timetable|time|exam|focus|revision|schedule/.test(q))key="study";else if(/goal|academic|marks|grade|semester|improve/.test(q))key="goal";else if(/skill|learn|project|certificate/.test(q))key="skills";else if(/career|job|intern|higher|course|placement/.test(q))key="career";else if(/mentor|meeting|talk|ask/.test(q))key="meeting";else if(/support|stress|worr|help|problem/.test(q))key="support";window.studentAIGuide(key);if(input)input.value=""};
