  window.saarthiRoleAsk=function(event){event.preventDefault();const q=String(document.getElementById("roleAiQuestion")?.value||"").toLowerCase();const role=activeUser?.role;let key=role==="faculty"?"mentees":role==="principal"?"progress":"progress";if(/follow|referr|intervention|due|overdue|support/.test(q))key="support";else if(/allocation|mentor|faculty|coverage/.test(q))key=role==="faculty"?"mentees":"coverage";else if(/interaction|session|record|meeting/.test(q))key=role==="faculty"?"record":"support";else if(/semester|final|review|development/.test(q))key="reviews";else if(/attention|incomplete|risk|concern/.test(q))key="attention";else if(/summary|word|report/.test(q))key="summary";else if(/goal|mentee|profile|progress|student/.test(q))key=role==="faculty"?"mentees":"progress";window.saarthiRoleAnswer(key);const input=document.getElementById("roleAiQuestion");if(input)input.value=""};
