/* Canonical roster names and HOD titles; migrate older browser-saved records on load. */
(function(){
  const canonical={"MTR022":"Ms. Varsha Dube","MTR038":"Ms. Puja Trivedi"};
  const deptNames=["Biosciences","Commerce","Computer Science","Humanities"];
  const hodById={"MTR016":"Biosciences","MTR032":"Computer Science","LOCAL-HUM-HOD-01":"Humanities","LOCAL-COM-HOD-01":"Commerce"};
  let changed=false;
  (db.mentors||[]).forEach(m=>{
    const id=String(m["Mentor ID"]||"");
    if(canonical[id]&&m["Mentor Name"]!==canonical[id]){m["Mentor Name"]=canonical[id];changed=true}
    if(hodById[id]&&(m.Department!==hodById[id]||m.Designation!=="HOD, "+hodById[id])){m.Department=hodById[id];m.Designation="HOD, "+hodById[id];changed=true}
    if(/^hod\b/i.test(String(m.Designation||"").trim())){
      const dept=deptNames.find(d=>String(m.Department||"").trim().toLowerCase()===d.toLowerCase());
      if(dept&&m.Designation!=="HOD, "+dept){m.Designation="HOD, "+dept;changed=true}
    }
  });
  (db.allocations||[]).forEach(a=>{
    const id=String(a["Mentor ID"]||"");
    if(canonical[id]&&a["Mentor Name"]!==canonical[id]){a["Mentor Name"]=canonical[id];changed=true}
    else if(/^(?:ms\.?\s*|miss\s*)?varsha\s+dube$/i.test(String(a["Mentor Name"]||"").trim())){a["Mentor Name"]=canonical.MTR022;changed=true}
    else if(/^(?:(?:ms|mrs)\.?\s*)?pooja\s+trivedi$/i.test(String(a["Mentor Name"]||"").trim())){a["Mentor Name"]=canonical.MTR038;changed=true}
  });
  if(changed&&typeof save==="function")save();
})();


/* Roster title and casing migration for current and browser-saved faculty records. */
(function(){
  const rosterSheet=(SOURCE_WORKBOOK_SHEETS||{})["3. MENTOR_MASTER"];
  const rosterIndex=new Map();
  if(rosterSheet){
    const ix=Object.fromEntries((rosterSheet.headers||[]).map((h,i)=>[h,i]));
    (rosterSheet.rows||[]).forEach(row=>{const id=String(row[ix["Mentor ID"]]||"").trim();if(id)rosterIndex.set(id,String(row[ix["Mentor Name"]]||"").trim())});
  }
  const formatMentorName=value=>{
    let text=String(value||"").trim().replace(/\s+/g," ");
    if(!text)return text;
    const match=text.match(/^(Dr|Ms|Mrs|Mr|Miss|Prof)\.?\s*(.*)$/i);
    let title,name;
    if(match){const key=match[1].toLowerCase();title={dr:"Dr.",ms:"Ms.",mrs:"Mrs.",mr:"Mr.",miss:"Miss",prof:"Prof."}[key];name=match[2]}
    else{title="Ms.";name=text}
    name=name.split(" ").filter(Boolean).map(part=>/^[A-Za-z]\.?$/.test(part)?part.toUpperCase():part.charAt(0).toUpperCase()+part.slice(1).toLowerCase()).join(" ");
    return title+(name?" "+name:"");
  };
  let changed=false;
  (db.mentors||[]).forEach(m=>{
    const id=String(m["Mentor ID"]||"").trim(),canonical=rosterIndex.get(id);
    const next=formatMentorName(canonical||m["Mentor Name"]);
    if(next&&m["Mentor Name"]!==next){m["Mentor Name"]=next;changed=true}
  });
  (db.allocations||[]).forEach(a=>{
    const id=String(a["Mentor ID"]||"").trim();
    const mentor=(db.mentors||[]).find(m=>String(m["Mentor ID"]||"").trim()===id);
    const next=formatMentorName(mentor?.["Mentor Name"]||a["Mentor Name"]);
    if(next&&a["Mentor Name"]!==next){a["Mentor Name"]=next;changed=true}
  });
  if(changed&&typeof save==="function")save();
})();


/* HOD primary and foreign key integrity view, scoped to the active department. */
(function(){
  function present(v){return String(v==null?"":v).trim()}
  var priorSaveAllocation=window.saveAllocation;
  window.saveAllocation=function(studentId){
    if(!["hod","admin"].includes(activeUser?.role)){toast("Only HOD can change mentor allocations");return}
    var st=(db.students||[]).find(function(x){return present(x["Student ID"])===String(studentId)});
    var mentorId=present(document.getElementById("mentorselect")?.value);
    var mentor=(db.mentors||[]).find(function(x){return present(x["Mentor ID"])===mentorId});
    if(!st||!studentId||!scopedStudents().some(function(x){return present(x["Student ID"])===String(studentId)})){toast("Choose a student in your department");return}
    if(!mentor||!mentorId||present(mentor.Status).toLowerCase()==="left"){toast("Choose an active mentor from the roster");return}
    if(activeUser?.role==="hod"&&String(mentor.Department||"").trim().toLowerCase()!==String(activeUser.department||"").trim().toLowerCase()){toast("HOD allocations stay within your department");return}
    var duplicates=(db.allocations||[]).filter(function(a){return present(a["Student ID"])===String(studentId)});
    if(duplicates.length>1){toast("Duplicate assignment records exist for this student; no changes were saved.");return}
    return priorSaveAllocation.apply(this,arguments);
  };
  var priorSaveSession=window.saveSession;
  window.saveSession=function(){
    if(activeUser?.role!=="faculty"){toast("Only assigned faculty mentors can record interactions");return}
    var form=document.getElementById("sessionform"),values=form?Object.fromEntries(new FormData(form).entries()):{};
    var student=scopedStudents().find(function(x){return present(x["Student ID"])===present(values["Student ID"])});
    var mentor=scopedMentors().find(function(x){return present(x["Mentor ID"])===present(values["Mentor ID"])});
    var assignment=(db.allocations||[]).find(function(x){return present(x["Student ID"])===present(values["Student ID"])&&present(x["Mentor ID"])});
    if(!student||!mentor||!assignment||present(assignment["Mentor ID"])!==present(values["Mentor ID"])){toast("Student and mentor IDs must match an active mentee allocation");return}
    var next="INT"+String((db.sessions||[]).length+1).padStart(4,"0");
    if((db.sessions||[]).some(function(x){return present(x["Interaction ID"])===next})){toast("A duplicate interaction ID would be created, so this record was not saved.");return}
    return priorSaveSession.apply(this,arguments);
  };
})();
